// ============================================================================
//   Determination of rational points for X: y^2 = x^6 - 9*x^2 + 9.
//   Using quadratic Chabauty (in Sage) and the Mordell-Weil sieve (here).
//   To replicate this analysis:
//
//   0. Be sure you have followed the installation instructions in the README 
//      to obtain all the required files.
//   1. Run Steps 1 and 2 in this file. It computes and prints
//      pts / gens / projE1E2 / ordinary_pr, for use in Step 3.
//   2. In Sage, copy the output of Step 2 into QuadraticChabautyAnalysis.sage to apply
//      quadratic Chabauty. It prints "all_fake_coeffs := ...;" as the main output.
//   3. Paste the printed all_fake_coeffs into the `all_fake_coeffs :=`
//      position, then run steps 3 through 5 to execute the sieve. 
// ============================================================================

//////////////////////////////////////////////////////////////////////////////
// Step 1: Load relevant files and define the curve.
//////////////////////////////////////////////////////////////////////////////

load "NewFunctions.m"; 
load "MWSieveCode.m";  

R<x> := PolynomialRing(Rationals());
X := HyperellipticCurve(x^6 - 9*x^2 + 9);
J := Jacobian(X);

//////////////////////////////////////////////////////////////////////////////
// Step 2: Mordell-Weil data, and projections of the MW basis to E1, E2.
//////////////////////////////////////////////////////////////////////////////

points := Points(X : Bound := 10000);
pts := Setseq(points);
base_pt := X!pts[1];

torsion_bas, torsion_orders, bas := generators(J);
gens := [Eltseq(bas[1]), Eltseq(bas[2])];

P1 := elt<J | bas[1][1], bas[1][2], bas[1][3]>;
P2 := elt<J | bas[2][1], bas[2][2], bas[2][3]>;
projE1E2 := [ellproj(P1), ellproj(P2)];

D := Degree2Subcovers(X);
E1 := MinimalModel(D[1][1]);
E2 := MinimalModel(D[2][1]);
Primes := PrimesInInterval(3,100);
GoodPrimes := [p : p in Primes | p in BadPrimes(X) eq false];
OP := [p : p in GoodPrimes | IsOrdinary(ChangeRing(E1,GF(p))) and IsOrdinary(ChangeRing(E2,GF(p)))];
ordinary_pr := [OP[i] : i in [1..3]];

print "pts:"; print pts; 
// [ (1 : -1 : 0), (1 : 1 : 0), (-1 : -1 : 1), (-1 : 1 : 1), (0 : -3 : 1), (0 : 3 : 1),
// (1 : -1 : 1), (1 : 1 : 1), (-3 : -3 : 2), (-3 : 3 : 2), (3 : -3 : 2), (3 : 3 : 2) ]
print "gens:"; print gens;
// [[1, x^3], [x + 1, x^3]]
print "projE1E2:"; print projE1E2;
// [[ (0 : 1 : 0), (9 : -9 : 1) ], [ (1 : -1 : 1), (0 : -9 : 1) ]]
print "ordinary_pr:"; print ordinary_pr;
//[ 5, 7, 11 ]

