//////////////////////////////////////////////////////////////////////////////
// Step 4: sieving-prime precomputation. 
//////////////////////////////////////////////////////////////////////////////

N := 4; //exponent for all QC primes
exponents := [N : p in ordinary_pr];
B := BadPrimes(X);
AA := 10^4;
A := PrimesUpTo(AA);
for v in B do
  A := Exclude(A, v);
end for;
groups := [];
for i in [1..#A] do
  groups[i] := AbelianGroup(Jacobian(ChangeRing(X, GF(A[i]))));
end for;
qc_M := &*[ordinary_pr[i]^exponents[i] : i in [1..#ordinary_pr]];

MWSPrimes1 := sieving_primes(qc_M*1, A, groups, 0.5 : printlevel := 0);
print "MWSPrimes1:"; print MWSPrimes1;
//[ 29, 61, 113, 877, 1279, 1291, 2687, 2713, 3547, 3643, 4219 ]
MWSPrimes2 := sieving_primes(qc_M*2, A, groups, 0.5 : printlevel := 0);
print "MWSPrimes2:"; print MWSPrimes2;
//[ 29, 61, 113, 271, 397, 593, 877, 1117, 1279, 1291, 1747, 2467, 2687, 2713,
//3511, 3547, 3643, 4219, 4337, 5399, 7757 ]
MWSPrimes4 := sieving_primes(qc_M*4, A, groups, 0.5 : printlevel := 0);
print "MWSPrimes4:"; print MWSPrimes4;
//[ 29, 37, 53, 61, 107, 109, 113, 163, 199, 271, 359, 379, 397, 523, 593, 631,
//647, 877, 937, 1117, 1277, 1279, 1291, 1747, 2143, 2179, 2269, 2467, 2503, 2687,
//2713, 2791, 3511, 3547, 3643, 3761, 4219, 4229, 4337, 5399, 5507, 6301, 7757, 8011, 8641 ]

T := TorsionSubgroup(J);
print "Torsion subgroup:"; print T;
//T = Z/3; curve is in T3

//////////////////////////////////////////////////////////////////////////////
// Step 5: run the Mordell-Weil sieve. 
//////////////////////////////////////////////////////////////////////////////

Failed := [];
done_fake := [false : i in [1..#all_fake_coeffs[1]]];
done_pr := [[] : i in [1..#all_fake_coeffs[1]]];
necessary_pr := [[] : i in [1..#all_fake_coeffs[1]]];

AuxSet := [3]; //for non-trivial torsion we may have to use aux_int > 1
K := #ordinary_pr; //number of QC primes used
//try every (K-1)-subset of the K QC primes (cheaper) before falling back to all K together
ind_options := [Sort(Setseq(s)) : s in Subsets(Set([1..K]), K-1)] cat [[1..K]];
fake_all_om := all_fake_coeffs[1];

for om in [1..#all_fake_coeffs[1][1]] do
  "Omega", om, "out of", #all_fake_coeffs[1][1];
    fake := [fake_all_om[1][om],fake_all_om[2][om],fake_all_om[3][om]];
  //if there are no fake points for one of the QC primes, we can bypass the sieve
  if [] in fake then
    print "easy";
    done_fake[om] := true;
    done_pr[om] := [0];
    continue;
  end if;
  for ind in ind_options do
    ordinary_primes := [ordinary_pr[i] : i in ind];
    print ordinary_primes;
    exps := [N : p in ordinary_primes];
    ordinary_M := &*[ordinary_primes[i]^exps[i] : i in [1..#ordinary_primes]]; //modulus prior to adding aux_int
    aux_int := 1; //the default aux_int
    print "aux_int =", aux_int;
    M := ordinary_M*aux_int; // modulus after aux_int
    mws_primes := MWSPrimes1; //pre-computed above
    print("mws_primes"); print mws_primes;
    fake_coeffs := [];
    for i in ind do
      Append(~fake_coeffs, [fake[i]]);
    end for;
    printf "number of extra points: %o\n", [#fake[i] : i in [1..K]];
    ordinary_fake_coeffs_mod_M := coeffs_CRT(fake_coeffs, ordinary_primes, exps);
    printf "number of cosets: %o\n", #ordinary_fake_coeffs_mod_M;
    fake_coeffs_mod_M := combine_fake_good(ordinary_fake_coeffs_mod_M, ordinary_M, aux_int);
    printf "after aux_int: %o\n", #fake_coeffs_mod_M;
    if #torsion_bas eq 0 then //if the torsion is trivial
      fake_coeffs_new := fake_coeffs_mod_M;
    end if;
    if #torsion_bas eq 1 then //if torsion is generated by one element
      fake_coeffs_new := [**];
      for k in [0..torsion_orders[1]-1] do
        for i in [1..#fake_coeffs_mod_M] do
          Append(~fake_coeffs_new, [*fake_coeffs_mod_M[i][1], fake_coeffs_mod_M[i][2], Integers()!k*]);
        end for;
      end for;
    end if;
    if #torsion_bas eq 2 then //if torsion is generated by two elements
      fake_coeffs_new := [**];
      for k1 in [0..torsion_orders[1]-1] do
        for k2 in [0..torsion_orders[2]-1] do
          for i in [1..#fake_coeffs_mod_M] do
            Append(~fake_coeffs_new, [*fake_coeffs_mod_M[i][1], fake_coeffs_mod_M[i][2], Integers()!k1, Integers()!k2*]);
          end for;
        end for;
      end for;
    end if;
    printf "after torsion: %o\n", #fake_coeffs_new;
    d_f, necessary_primes1, bool_list := MWSieve(J, mws_primes, M, bas cat torsion_bas, base_pt, fake_coeffs_new); //run the sieve
    necessary_pr[om] := necessary_primes1;
    print "necessary primes", necessary_pr[om];
    if d_f then
      done_pr[om] := ordinary_primes cat [aux_int];
      done_fake[om] := true;
      print d_f, ordinary_primes cat [aux_int];
      break ind;
    end if;
    Left := [fake_coeffs_new[i] : i in [1..#fake_coeffs_new] | bool_list[i] eq true]; //cosets left over for aux_int = 1
    if d_f eq false then //if aux_int = 1 does not succeed, try aux_int > 1
      for aux_int in AuxSet do
        print "Attention aux_int is", aux_int;
        printf "number of cosets: %o\n", #Left;
        M := ordinary_M*aux_int;
        fake_coeffs_mod_M := combine_fake_good(Left, ordinary_M, aux_int); //factor in aux_int > 1
        printf "after aux_int: %o\n", #fake_coeffs_mod_M;
        fake_coeffs_new := fake_coeffs_mod_M;
        if aux_int eq 2 then //pre-computed above
          mws_primes := MWSPrimes2;
        end if;
        if aux_int eq 4 then //pre-computed above
          mws_primes := MWSPrimes4;
        end if;
        if aux_int in [2,4] eq false then //otherwise compute mws_primes now
          mws_primes := sieving_primes(M, A, groups, 0.5 : printlevel := 0);
        end if;
        print("mws_primes"); print mws_primes;
        d_f, necessary_primes2, bool_list := MWSieve(J, mws_primes, M, bas cat torsion_bas, base_pt, fake_coeffs_new);
        if d_f then //sieve succeeded: record the ordinary_primes and aux_int used for this Omega class
          necessary_pr[om] := necessary_primes1 cat necessary_primes2;
          print "necessary primes", necessary_pr[om];
          done_pr[om] := ordinary_primes cat [aux_int];
          done_fake[om] := true;
          print d_f, ordinary_primes cat [aux_int];
          break ind;
          break aux_int;
        end if;
      end for;
    end if;
  end for;
end for;

if false in done_fake then
  Failed := Failed cat [1];
end if;
print "Failed", Failed;
assert Failed eq [];

